import pandas as pd, numpy as np
from scipy import stats

for i in [1,3,4,5,6,7,9,10,11]:
    df = pd.read_csv(eval(f"experiment_{i}_csv"))
    print(f"=== exp {i} cols:", list(df.columns))
    if "JobThroughput" in df and "RackInletTemp" in df:
        s,inte,r,p,se = stats.linregress(df.RackInletTemp, df.JobThroughput)
        print(f"  Temp->Thru slope={s:.3f} r={r:.3f} p={p:.1e}")
    if "JobThroughput" in df:
        print("  Thru mean=%.2f"%df.JobThroughput.mean())
    print("  corr with Thru:")
    if "JobThroughput" in df:
        print(df.corr(numeric_only=True)["JobThroughput"].round(3).to_dict())
